import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { positionLocal, normalLocal, uv, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const outer = new Group();
  const inner = new Group();
  outer.add(inner);

  // Spec palette
  const paperColor   = new THREE.Color('#e8ecf2');
  const accentColor  = new THREE.Color('#ff2a38');
  const surfaceColor = new THREE.Color('#0b0b10');

  // Compact metric card dimensions (~1.6 x 1.0)
  const W = 1.6, H = 1.0;

  // TSL displacement uniform (subtle, machined surface relief)
  const displacementAmount = uniform(0.12);

  // --- Card body: tessellated plane with depth-driven displacement ---
  const geometry = new PlaneGeometry(W, H, 64, 64);

  const material = new MeshStandardNodeMaterial({
    color:    new THREE.Color(surfaceColor.getHex()),
    roughness: 0.55,
    metalness: 0.45,
  });

  // Base albedo (atlas row texture, applied via legacy map slot — auto-coerced to TSL)
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    material.map = tex;
    material.needsUpdate = true;
  });

  // Depth-driven vertex displacement via TSL positionNode
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
    const depthSample = texture(depthTex, uv()).r;
    material.positionNode = positionLocal.add(
      normalLocal.mul(depthSample.mul(displacementAmount))
    );
    material.needsUpdate = true;
  });

  const cardMesh = new Mesh(geometry, material);
  inner.add(cardMesh);

  // --- Accent edge frame behind the card (focus/hover indicator) ---
  const edgeGeom = new PlaneGeometry(W + 0.06, H + 0.06);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: new THREE.Color(accentColor.getHex()),
    transparent: true,
    opacity: 0.0,
  });
  const edgeMesh = new Mesh(edgeGeom, edgeMaterial);
  edgeMesh.position.z = -0.03;
  inner.add(edgeMesh);

  // --- Local lighting: rim (accent) + back fill, paired with the lit backdrop ---
  const rimLight = new THREE.DirectionalLight(new THREE.Color(accentColor.getHex()), 0.6);
  rimLight.position.set(-1.6, 0.8, -1.4);
  inner.add(rimLight);

  const backFill = new THREE.DirectionalLight(new THREE.Color(paperColor.getHex()), 0.4);
  backFill.position.set(1.4, -0.6, -1.0);
  inner.add(backFill);

  // --- Contact shadow plane (grounded weight) ---
  const shadowGeom = new THREE.PlaneGeometry(W * 1.3, H * 0.32);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new THREE.Color(0x000000),
    transparent: true,
    opacity: 0.45,
  });
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.y = -H * 0.55;
  shadowMesh.position.z = -0.05;
  shadowMesh.rotation.x = -Math.PI * 0.5 * 0.0; // keep coplanar-ish under card
  inner.add(shadowMesh);

  // --- Entrance: rise-in (y +0.4 -> 0, power3.out, 0.7s) + weighted-settle 1.04 -> 1.0 ---
  inner.position.y = 0.4;
  inner.scale.setScalar(1.04);

  const entryTl = gsap.timeline();
  entryTl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  entryTl.to(inner.scale, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' }, '-=0.35');

  const timelines = [entryTl];
  const cleanups  = [];

  // --- Interactions ---
  outer.userData.handlers = {
    onPointerEnter: () => {
      // preset:rise-in subtle (0.15 scene units lift)
      gsap.to(inner.position, { y: 0.15, duration: 0.5, ease: 'power3.out', overwrite: 'auto' });
      // accent edge on focus/hover
      gsap.to(edgeMaterial, { opacity: 0.85, duration: 0.4, ease: 'power2.out' });
      // slight breathing on displacement for tactile depth
      gsap.to(displacementAmount, { value: 0.17, duration: 0.4, ease: 'power2.out' });
    },
    onPointerLeave: () => {
      gsap.to(inner.position, { y: 0, duration: 0.5, ease: 'power3.out', overwrite: 'auto' });
      gsap.to(edgeMaterial, { opacity: 0.0, duration: 0.4, ease: 'power2.out' });
      gsap.to(displacementAmount, { value: 0.12, duration: 0.45, ease: 'power2.out' });
    },
    onClick: () => {
      // emit:hub-features.select
      ctx.emit('hub-features.select', {});

      // press-down: scale 0.97 120ms back.out -> weighted-settle 1.04 -> 1.0
      const pressTl = gsap.timeline();
      pressTl
        .to(inner.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' })
        .to(inner.scale, { x: 1.04, y: 1.04, duration: 0.35, ease: 'power4.out' })
        .to(inner.scale, { x: 1.0, y: 1.0, duration: 0.55, ease: 'power3.out' });
      timelines.push(pressTl);
    },
  };

  // --- Apply cinematic primitives (parallax-scroll on outer to compose with adapter scenePosition) ---
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const p of config.cinematicPrimitives) {
      if (p.name && typeof ctx.primitives[p.name] === 'function') {
        const r = ctx.primitives[p.name](outer, p.params);
        if (r && r.cleanup)   cleanups.push(r.cleanup);
        if (r && r.timeline)  timelines.push(r.timeline);
      }
    }
  }

  // --- Cleanup ---
  outer.userData.cleanup = () => {
    timelines.forEach((t) => { try { t.kill(); } catch (_) {} });
    cleanups.forEach((c) => { try { c(); } catch (_) {} });
    geometry.dispose();
    material.dispose();
    edgeGeom.dispose();
    edgeMaterial.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    if (rimLight.dispose)  rimLight.dispose();
    if (backFill.dispose)  backFill.dispose();
  };

  return outer;
}
